target_repairs = {
    "C-588:counterfact_visual:T1:O0:B0",
    "C-353:counterfact_visual:T1:O0:B1",
    "C-353:counterfact_visual:T1:O1:B0",
    "C-119:counterfact_visual:T0:O1:B1"
}
